from functools import lru_cache
@lru_cache(None)
def fib(n): return n if n<2 else fib(n-1)+fib(n-2)
print(fib(int(input())))

def factorial(n):
    if n < 0: raise ValueError('n must be non-negative')
    return 1 if n <= 1 else n*factorial(n-1)
print(factorial(int(input())))

